In Chapter 10, subsection 10.3.1 "Getting started", the app that dynamically creates input control,  would throw an error when combines with `isolate()`.

Here is the code used to create the app: 
```R
library(shiny)

ui <- fluidPage(
    textInput("label", "label"),
    selectInput("type", "type", c("slider", "numeric")),
    uiOutput("numeric")
    
)

server <- function(input, output, session) {
    output$numeric <- renderUI({
        value <- isolate(input$dynamic)
        if (input$type == "slider") {
            sliderInput("dynamic", input$label, value = value, min = 0, max = 10)
        } else {
            numericInput("dynamic", input$label, value = value, min = 0, max = 10)
        }
    })

}

shinyApp(ui = ui, server = server)
```
It throws error at initialization. 
![image](https://user-images.githubusercontent.com/55836943/134305203-84821f91-f085-42b5-a678-e0590476beb0.png)

At app initialization, `input$dynamic` is `NULL` which rise the error. It could be fixed with `value=0` (like default) when `input$dynamic` is `NULL`:

```R
library(purrr)

server <- function(input, output, session) {
    output$numeric <- renderUI({
        value <- isolate(input$dynamic)
        if (input$type == "slider") {
            sliderInput("dynamic", input$label, value = value %||% 0, min = 0, max = 10)
        } else {
            numericInput("dynamic", input$label, value = value %||% 0, min = 0, max = 10)
        }
    })

}
```

TL;DR: At initialization, the module server returns `NULL`, as long as `choices` of `selectInput()` is set to `NULL`. 

Consider the following module: 

```
selectVarInput <- function(id) {
  selectInput(NS(id, "var"), "Variable", choices = NULL) 
}

selectVarServer <- function(id, data, filter = is.numeric) {
  moduleServer(id, function(input, output, session) {
    observeEvent(data(), {
      updateSelectInput(session, "var", choices = find_vars(data(), filter))
    })
    
    reactive(data()[[input$var]])
  })
}
```

At initialization, first, `input$var` has `""` value, and the module `selectVarServer()` returns respectively `NULL` (data()[[""]]). Only after a moment, `observeEvent()` updates choices of the `input$var, and picks by default the first one. In this example, it is not critical, since `renderPrint()` can handle `NULL`. But if we would have to render a plot, for instance, the error would be displayed for a sec. See this reproducible example below: 

```
library(tidyverse)

datasetInput <- function(id, filter = NULL) {
  names <- ls("package:datasets")
  if (!is.null(filter)) {
    data <- lapply(names, get, "package:datasets")
    names <- names[vapply(data, filter, logical(1))]
  }
  
  selectInput(NS(id, "dataset"), "Pick a dataset", choices = names)
}

datasetServer <- function(id) {
  moduleServer(id, function(input, output, session) {
    reactive(get(input$dataset, "package:datasets"))
  })
}

selectVarInput <- function(id) {
  selectInput(NS(id, "var"), "Variable", choices = NULL) 
}

find_vars <- function(data, filter) {
  names(data)[vapply(data, filter, logical(1))]
}

selectVarServer <- function(id, data, filter = is.numeric) {
  moduleServer(id, function(input, output, session) {
    observeEvent(data(), {
      updateSelectInput(session, "var", choices = find_vars(data(), filter))
    })
    
    reactive(data()[[input$var]])
  })
}

selectVarApp <- function(filter = is.numeric) {
  ui <- fluidPage(
    datasetInput("data", is.data.frame),
    selectVarInput("var"),
    plotOutput("out")
  )
  server <- function(input, output, session) {
    data <- datasetServer("data")
    var <- selectVarServer("var", data, filter = filter)
    output$out <- renderPlot(
      var() %>% 
        as_tibble() %>% 
        ggplot() + 
        geom_histogram(aes(x = value))
    )
  }
  
  shinyApp(ui, server)
}

selectVarApp()
```

The easy fix I see is to provide default choices of the first dataset and set `observeEvent`'s `ignoreInit` to `TRUE`: 

```
library(tidyverse)

datasetInput <- function(id, filter = NULL) {
  names <- ls("package:datasets")
  if (!is.null(filter)) {
    data <- lapply(names, get, "package:datasets")
    names <- names[vapply(data, filter, logical(1))]
  }
  
  selectInput(NS(id, "dataset"), "Pick a dataset", choices = names)
}

datasetServer <- function(id) {
  moduleServer(id, function(input, output, session) {
    reactive(get(input$dataset, "package:datasets"))
  })
}

# define default choices 🤘
default_var_choices <- names(airquality)

selectVarInput <- function(id) {
  # set default choices 🤘
  selectInput(NS(id, "var"), "Variable", choices = default_var_choices) 
}

find_vars <- function(data, filter) {
  names(data)[vapply(data, filter, logical(1))]
}

selectVarServer <- function(id, data, filter = is.numeric) {
  moduleServer(id, function(input, output, session) {
    
    # disable trigger at initialization 🤘
    observeEvent(data(), {
      updateSelectInput(session, "var", choices = find_vars(data(), filter)), 
      ignoreInit = TRUE
    })
    
    reactive(data()[[input$var]])
  })
}

selectVarApp <- function(filter = is.numeric) {
  ui <- fluidPage(
    datasetInput("data", is.data.frame),
    selectVarInput("var"),
    plotOutput("out")
  )
  server <- function(input, output, session) {
    data <- datasetServer("data")
    var <- selectVarServer("var", data, filter = filter)
    output$out <- renderPlot(
      var() %>% 
        as_tibble() %>% 
        ggplot() + 
        geom_histogram(aes(x = value))
    )
  }
  
  shinyApp(ui, server)
}

selectVarApp()
```

