There are two datasets that give errors in the shiny output - these are eurodist and UScitiesD.  It seems because they cannot convert to data.frame directly.

This can be fixed with:
```
library(shiny)
library(reshape)
ui <- fluidPage(
  selectInput("dataset", label = "Dataset", choices = ls("package:datasets")),
  verbatimTextOutput("summary"),
  tableOutput("table")
)
server <- function(input, output, session) {
  output$summary <- renderPrint({
    dataset <- get(input$dataset, "package:datasets")
    summary(dataset)
  })
  
  output$table <- renderTable({
    dataset <- get(input$dataset, "package:datasets")
    if("dist" %in% class(dataset)){
      dataset <- dataset %>% 
        as.matrix() %>%
        melt(varnames = c("from", "to"))
    }
    dataset
  })
}
shinyApp(ui, server)
```

