@MayaGans stumbled on an issue with the question asked in 8.1.5.4: you're asked add `""` as an option for displaying countries from all continents. It seems that the `""` entry disappears when you select any other continent. I was able to reproduce this and found that if you use `"All"` instead of `""` the All entry persists and can be selected again. 

Not sure if this is a bug that should be raised on the Shiny repo or if this is intentional and the question should ask about using "All" as the entry instead? 

_Code for_ `""`
``` 
library(shiny)
library(gapminder)

continents <- unique(gapminder$continent)

ui <- fluidPage(
  selectInput("continent", "Continent", choices = c("", as.character(continents))), 
  selectInput("country", "Country", choices = NULL),
  tableOutput("data")
)

server <- function(input, output, session) {
  selected_data <- reactive({
    if(input$continent %in% continents) {
      gapminder %>% 
      filter(continent == input$continent)
    } else {
      gapminder
    }
  })
    
  observeEvent( input$continent, {
    updateSelectInput(session, "country", "Country",
                      choices = selected_data() %>% 
                        select(country) %>%
                        distinct())
  })  
  output$data <- renderTable({ 
    selected_data() %>% 
      filter(country == input$country) 
  })
}

shinyApp(ui = ui, server = server)
```

_Code for_ `"All"` 
```
library(shiny)
library(gapminder)

continents <- unique(gapminder$continent)

ui <- fluidPage(
  selectInput("continent", "Continent", choices = c("All", as.character(continents))), 
  selectInput("country", "Country", choices = NULL),
  tableOutput("data")
)

server <- function(input, output, session) {
  selected_data <- reactive({
    if(input$continent %in% continents) {
      gapminder %>% 
      filter(continent == input$continent)
    } else {
      gapminder
    }
  })
    
  observeEvent( input$continent, {
    updateSelectInput(session, "country", "Country",
                      choices = unique(selected_data()$country))
  })  
  output$data <- renderTable({ 
    selected_data() %>% 
      filter(country == input$country) 
  })
}

shinyApp(ui = ui, server = server)
```

